<script setup>
import SourceBadge from '../components/SourceBadge.vue'
import {computed,ref,onMounted} from 'vue'
import {useLearning} from '../stores/learning'
import {subjects,subjectMap} from '../data/quiz'
import QuizRunner from '../components/QuizRunner.vue'
import PartnerImage from '../components/PartnerImage.vue'
import GameHeader from '../components/GameHeader.vue'
const store=useLearning(),source=ref('all'),subject=ref('all'),status=ref('all'),reviewing=ref(false)
const filtered=computed(()=>store.mistakes.filter(m=>(source.value==='all'||(m.source??'official')===source.value)&&(subject.value==='all'||m.subject===subject.value)&&(status.value==='all'||(status.value==='done'?m.reviewed:!m.reviewed))))
async function review(ids){if(await store.startReview(ids))reviewing.value=true}
function exit(){reviewing.value=false;store.load()}
onMounted(()=>store.load())
</script>
<template><GameHeader tag="MY LITTLE FRIEND / REVIEW NOTE" title="틀린 문제!" description="틀려도 괜찮아요. 파트너와 다시 풀며 내 지식으로 만들어 봐요. 오답은 계정별로 자동 저장됩니다."/><p v-if="store.error" class="notice" role="alert">{{store.error}}</p><div class="pet-study-menu"><RouterLink to="/pet" class="button light">← 파트너 돌보기</RouterLink><RouterLink to="/quiz" class="button light">새 퀴즈 풀기 →</RouterLink><RouterLink to="/pet/mailbox" class="button light">내 쪽지함 →</RouterLink></div><QuizRunner v-if="reviewing&&store.state.activeReview" review @exit="exit"/><section v-else class="panel mistakes-panel"><div class="mistakes-header"><PartnerImage size="small"/><div><h2>나만의 오답 노트</h2><p>전체 {{store.mistakes.length}}문제 · 복습 필요 {{store.pendingCount}}문제 · 복습 완료 {{store.mistakes.filter(m=>m.reviewed).length}}문제</p></div></div><div v-if="store.state.activeReview&&!store.state.activeReview.done" class="welcome-strip study-resume"><span>진행 중인 복습이 있어요.</span><button @click="reviewing=true">복습 이어서 풀기</button></div><div class="mistake-filters"><label>문제 출처<select v-model="source"><option value="all">전체</option><option value="official">공식</option><option value="student">학생 제작</option></select></label><label>과목<select v-model="subject"><option value="all">전체 과목</option><option v-for="s in subjects" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>복습 상태<select v-model="status"><option value="all">전체 상태</option><option value="pending">복습 필요</option><option value="done">복습 완료</option></select></label><button :disabled="!filtered.some(m=>!m.locked)" @click="review(filtered.filter(m=>!m.locked).map(m=>m.id))">틀린 문제 다시 풀기 ({{filtered.filter(m=>!m.locked).length}})</button></div><div v-if="!store.mistakes.length" class="empty study-empty"><PartnerImage size="large"/><h2>아직 틀린 문제가 없어요!</h2><p>퀴즈에서 틀린 문제가 생기면 이곳에 자동으로 모아 드려요.</p><RouterLink to="/quiz" class="button">퀴즈 타임 시작 →</RouterLink></div><div v-else-if="!filtered.length" class="study-empty"><h3>선택한 조건에 해당하는 문제가 없어요.</h3><p>과목이나 복습 상태를 바꿔 확인해 보세요.</p></div><template v-else><p class="study-notice">정답과 해설은 ‘답안·해설 확인’을 열면 볼 수 있어요. 최초 정답 보상은 관리자 설정을 따릅니다. 자기 문제는 미지급이며 원본·수정 버전을 합쳐 한 번만 보상합니다.</p><article v-for="m in filtered" :key="m.id" class="mistake-entry"><SourceBadge :source="m.source" :creator-name="m.creatorName" :creator-id="m.creatorId" :post-id="m.postId" :version="m.version"/><div class="mistake-entry-meta"><span>{{subjectMap[m.subject]?.name}}</span><span :class="['review-badge',{completed:m.reviewed}]">{{m.reviewed?'✓ 복습 완료':'! 복습 필요'}}</span><small>오답 {{m.wrongCount}}회</small></div><h3>{{m.locked?'🔒 아직 배우지 않은 단원입니다':m.question}}</h3><template v-if="!m.locked"><p><b>최근 내가 쓴 답:</b> {{m.lastAnswer}}</p><p v-if="m.reviewed"><b>마지막 오답:</b> {{m.lastWrongAnswer}}</p><details><summary>답안·해설 확인</summary><p><b>정답:</b> {{m.correctAnswer}}</p><p>{{m.explanation}}</p></details><div class="mistake-entry-bottom"><small>{{new Date(m.updatedAt).toLocaleString('ko-KR')}}</small><button @click="review([m.id])">이 문제 다시 풀기</button></div></template></article></template></section></template>
